float opRoundingByUv_UvMask1(in vec2 uv, float animSpeedX, float animSpeedY)
{
    uv.x += 1.0 * sin(animSpeedX * iTime);
    uv.y += 1.0 * sin(animSpeedY * iTime);

    //return 1.0 - abs(uv.x);
    //return 1.0 - length(uv);
    return clamp(1.2 * pow(1.0 - abs(length(uv)), 2.0), 0.0, 1.0);
    //return 1.0 - clamp(1.2 * pow(1.0 - abs(length(uv)), 2.0), 0.0, 1.0);
}

void opRoundingByUv(inout float dist, in float radius, float radiusByUv, float animSpeedX, float animSpeedY)
{
    float param01 = opRoundingByUv_UvMask1(g_uv, animSpeedX, animSpeedY);
    //float param01 = opRoundingByUv_UvMask1(vec2(1.0, 1.0));

    dist -= (radius + radiusByUv * param01);
}
